// Détection YouTube et extraction ID
const renderMarkdown = (txt) => {
  if(!txt) return "";
  const lines = txt.split("\n");
  let html = "";
  let inTable = false;
  let tableHtml = "";
  let firstTableRow = true;

  lines.forEach((line) => {
    const trimmed = line.trim();
    // Pipe table
    if(trimmed.startsWith("|") && trimmed.endsWith("|")) {
      const isSep = trimmed.replace(/[|\s\-:]/g,"") === "";
      if(!inTable) {
        inTable = true;
        firstTableRow = true;
        tableHtml = '<table style="border-collapse:collapse;width:100%;margin:10px 0;direction:rtl">';
      }
      if(isSep) {
        firstTableRow = false;
        return;
      }
      const cells = trimmed.split("|").filter((_,i,a)=>i>0&&i<a.length-1);
      const tag = firstTableRow ? "th" : "td";
      const style = firstTableRow
        ? 'style="border:1px solid #aaa;padding:7px 12px;background:#e8f4ee;text-align:right;font-weight:bold"'
        : 'style="border:1px solid #ccc;padding:6px 12px;text-align:right"';
      tableHtml += "<tr>" + cells.map(c=>`<${tag} ${style}>${c.trim()}</${tag}>`).join("") + "</tr>";
      if(firstTableRow) firstTableRow = false;
    } else {
      if(inTable) { html += tableHtml + "</table>"; inTable=false; tableHtml=""; firstTableRow=true; }
      // Inline formatting
      let l = line
        .replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")
        .replace(/\*\*(.*?)\*\*/g,"<strong>$1</strong>")
        .replace(/__(.*?)__/g,"<u>$1</u>")
        .replace(/\*(.*?)\*/g,"<em>$1</em>")
        .replace(/\[center\](.*?)\[\/center\]/g,"<div style='text-align:center'>$1</div>")
        .replace(/^\[center\](.*)/,"<div style='text-align:center'>$1</div>")
        .replace(/^• (.*)/, "<li style='margin:2px 0;padding-right:8px'>$1</li>")
        .replace(/^- (.*)/, "<li style='margin:2px 0;padding-right:8px'>$1</li>");
      // Handle multiline [center] blocks
      if(l.includes("[center]")) l = l.replace(/\[center\]/g,"<div style='text-align:center'>").replace(/\[\/center\]/g,"</div>");
      html += l + (l.startsWith("<li") || l.startsWith("<div") ? "" : "<br/>");
    }
  });
  if(inTable) html += tableHtml + "</table>";
  return html;
};
const renderText = renderMarkdown;

const getYoutubeId = (url) => {
  if(!url) return null;
  const m = url.match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([\w-]{11})/);
  return m ? m[1] : null;
};
const isImageUrl = (url) => {
  if(!url) return false;
  return /\.(jpg|jpeg|png|gif|webp|svg)$/i.test(url) || url.includes('supabase') && url.includes('comptes-rendus');
};

