// FORMULAIRE D'INSCRIPTION (PROSPECT)
// ════════════════════════════════════════════════════════════════
function InscriptionPage({onBack, onSuccess}) {
  const empty = {cin:"",nom:"",prenom:"",email:"",pwd:"",pwd2:"",profil_souhaite:"membre",type_compte:"physique",etablissement:"",message:""};
  const [form,setForm]=useState(empty);
  const [err,setErr]=useState("");
  const [saving,setSaving]=useState(false);
  const [done,setDone]=useState(false);

  const upd = (k,v) => { setForm(p=>({...p,[k]:v})); setErr(""); };

  const submit = async () => {
    if(!form.cin||!form.nom||!form.email||!form.pwd||!form.telephone){setErr("يرجى ملء جميع الحقول الإلزامية (*)");return;}
    if(form.type_compte==="physique"&&form.cin.length<8){setErr("رقم بطاقة التعريف يجب أن يحتوي على 8 أرقام على الأقل");return;}
    if(form.pwd.length<8){setErr("كلمة السر يجب أن تحتوي على 8 أحرف على الأقل");return;}
    if(form.pwd!==form.pwd2){setErr("كلمتا السر غير متطابقتين");return;}
    setSaving(true);
    // Vérifier si CIN déjà existant
    const existing = await supa.getDemandesByCin(form.cin);
    const enAttente = existing.filter(d=>d.statut==="en_attente");
    if(enAttente.length>0){setErr("يوجد طلب قيد الانتظار بنفس رقم الهوية");setSaving(false);return;}
    const membreExist = await supa.getMembreByCin(form.cin);
    if(membreExist){setErr("هذا الرقم مسجّل مسبقاً كعضو في الجمعية");setSaving(false);return;}
    const {error} = await supa.addDemande({cin:form.cin,nom:form.nom,prenom:form.prenom,email:form.email,pwd_hash:simpleHash(form.pwd),profil_souhaite:form.profil_souhaite,type_compte:form.type_compte,etablissement:form.etablissement,message:form.message,telephone:form.telephone||""    ,statut:"en_attente"});
    if(error){setErr("خطأ في التسجيل: "+error.message);setSaving(false);return;}
    setDone(true);
    setSaving(false);
  };

  if(done) return (
    <div style={{minHeight:"100vh",background:`linear-gradient(160deg,${C.forest} 0%,#091a10 100%)`,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Cairo',sans-serif",direction:"rtl",padding:24}}>
      <div style={{textAlign:"center",maxWidth:420}}>
        <div style={{fontSize:64,marginBottom:20}}>✅</div>
        <h2 style={{color:C.mist,fontWeight:"normal",margin:"0 0 12px"}}>تم إرسال طلبك بنجاح!</h2>
        <p style={{color:"#4a7a60",lineHeight:1.8,marginBottom:28}}>سيتم مراجعة طلبك من قِبل مدير الجمعية وستتلقى ردًا في أقرب وقت ممكن.</p>
        <button onClick={onBack} style={{padding:"12px 28px",background:"linear-gradient(135deg,#2e6b47,#4a9e68)",border:"none",borderRadius:11,color:"#e8f5ec",fontSize:15,cursor:"pointer",fontFamily:"'Cairo',sans-serif"}}>
          العودة إلى الصفحة الرئيسية
        </button>
      </div>
    </div>
  );

  return (
    <div style={{minHeight:"100vh",background:`linear-gradient(160deg,${C.forest} 0%,#091a10 100%)`,fontFamily:"'Cairo',sans-serif",direction:"rtl",padding:"32px 16px"}}>
      <div style={{maxWidth:560,margin:"0 auto"}}>
        <div style={{textAlign:"center",marginBottom:28}}>
          <img src={apsvtLogo} alt="APSVT" style={{width:60,height:60,borderRadius:"50%",objectFit:"contain",background:"rgba(255,255,255,0.92)",padding:4,marginBottom:12}}/>
          <h2 style={{color:C.mist,fontWeight:"normal",margin:"0 0 4px",fontSize:22}}>طلب الانخراط في الجمعية</h2>
          <p style={{color:"#4a7a60",fontSize:12,margin:0}}>APSVT — سيتم مراجعة طلبك من قِبل الإدارة</p>
        </div>

        <div style={{background:"rgba(255,255,255,.04)",border:"1px solid rgba(180,220,200,.15)",borderRadius:20,padding:"28px 32px"}}>

          {/* Choix du profil */}
          <div style={{marginBottom:20}}>
            <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:10,fontFamily:"sans-serif"}}>نوع الانخراط *</label>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
              {PROFILS_PROSPECT.map(p=>(
                <div key={p.value} onClick={()=>upd("profil_souhaite",p.value)}
                  style={{padding:"10px 14px",borderRadius:10,border:`2px solid ${form.profil_souhaite===p.value?"#4a9e68":"rgba(180,220,200,.2)"}`,background:form.profil_souhaite===p.value?"rgba(74,158,104,.15)":"transparent",cursor:"pointer",display:"flex",alignItems:"center",gap:8,transition:"all .15s"}}>
                  <span style={{fontSize:20}}>{p.icon}</span>
                  <div><div style={{color:C.mist,fontSize:13}}>{p.label}</div><div style={{color:"#4a7a60",fontSize:10,fontFamily:"sans-serif"}}>{p.desc}</div></div>
                </div>
              ))}
            </div>
          </div>

          {/* Type de compte */}
          <div style={{marginBottom:16}}>
            <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:8,fontFamily:"sans-serif"}}>نوع الحساب *</label>
            <div style={{display:"flex",gap:10}}>
              {[["physique","شخص طبيعي","🪪"],["morale","شخص معنوي","🏢"]].map(([v,l,i])=>(
                <div key={v} onClick={()=>upd("type_compte",v)}
                  style={{flex:1,padding:"10px",borderRadius:10,border:`2px solid ${form.type_compte===v?"#4a9e68":"rgba(180,220,200,.2)"}`,background:form.type_compte===v?"rgba(74,158,104,.15)":"transparent",cursor:"pointer",textAlign:"center",transition:"all .15s"}}>
                  <div style={{fontSize:22,marginBottom:4}}>{i}</div>
                  <div style={{color:C.mist,fontSize:13}}>{l}</div>
                </div>
              ))}
            </div>
          </div>

          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
            <div style={{gridColumn:"1 / -1"}}>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:6,fontFamily:"sans-serif"}}>
                {form.type_compte==="physique"?"رقم بطاقة التعريف الوطنية *":"المعرّف الجبائي الوحيد *"}
              </label>
              <input value={form.cin} onChange={e=>upd("cin",e.target.value)} placeholder={form.type_compte==="physique"?"00000000":"00000000A"}
                style={{width:"100%",padding:"11px 14px",background:"rgba(255,255,255,.06)",border:"1.5px solid rgba(180,220,200,.2)",borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
            </div>
            <div>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:6,fontFamily:"sans-serif"}}>اللقب *</label>
              <input value={form.nom} onChange={e=>upd("nom",e.target.value)}
                style={{width:"100%",padding:"11px 14px",background:"rgba(255,255,255,.06)",border:"1.5px solid rgba(180,220,200,.2)",borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
            </div>
            <div>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:6,fontFamily:"sans-serif"}}>الاسم</label>
              <input value={form.prenom} onChange={e=>upd("prenom",e.target.value)}
                style={{width:"100%",padding:"11px 14px",background:"rgba(255,255,255,.06)",border:"1.5px solid rgba(180,220,200,.2)",borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
            </div>
            <div style={{gridColumn:"1 / -1"}}>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:6,fontFamily:"sans-serif"}}>البريد الإلكتروني *</label>
              <input type="email" value={form.email} onChange={e=>upd("email",e.target.value)}
                style={{width:"100%",padding:"11px 14px",background:"rgba(255,255,255,.06)",border:"1.5px solid rgba(180,220,200,.2)",borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
            </div>
            <div style={{gridColumn:"1 / -1"}}>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:6,fontFamily:"sans-serif"}}>رقم الهاتف المحمول *</label>
              <input type="tel" value={form.telephone||""} onChange={e=>upd("telephone",e.target.value)} placeholder="+216 XX XXX XXX"
                style={{width:"100%",padding:"11px 14px",background:"rgba(255,255,255,.06)",border:"1.5px solid rgba(180,220,200,.2)",borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
            </div>
            <div>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:6,fontFamily:"sans-serif"}}>كلمة السر *</label>
              <div style={{position:"relative"}}>
                <input type={form.visPwd?"text":"password"} value={form.pwd} onChange={e=>upd("pwd",e.target.value)}
                  style={{width:"100%",padding:"11px 44px 11px 14px",background:"rgba(255,255,255,.06)",border:"1.5px solid rgba(180,220,200,.2)",borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
                <button type="button" onClick={()=>upd("visPwd",!form.visPwd)} style={{position:"absolute",left:12,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",color:"#5a8070",cursor:"pointer",fontSize:18}}>{form.visPwd?"🙈":"👁"}</button>
              </div>
            </div>
            <div>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:6,fontFamily:"sans-serif"}}>تأكيد كلمة السر *</label>
              <div style={{position:"relative"}}>
                <input type={form.visPwd2?"text":"password"} value={form.pwd2} onChange={e=>upd("pwd2",e.target.value)}
                  style={{width:"100%",padding:"11px 44px 11px 14px",background:"rgba(255,255,255,.06)",border:"1.5px solid rgba(180,220,200,.2)",borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
                <button type="button" onClick={()=>upd("visPwd2",!form.visPwd2)} style={{position:"absolute",left:12,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",color:"#5a8070",cursor:"pointer",fontSize:18}}>{form.visPwd2?"🙈":"👁"}</button>
              </div>
            </div>
            <div style={{gridColumn:"1 / -1"}}>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:6,fontFamily:"sans-serif"}}>المؤسسة / الشركة</label>
              <input value={form.etablissement} onChange={e=>upd("etablissement",e.target.value)}
                style={{width:"100%",padding:"11px 14px",background:"rgba(255,255,255,.06)",border:"1.5px solid rgba(180,220,200,.2)",borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif"}}/>
            </div>
            <div style={{gridColumn:"1 / -1"}}>
              <label style={{display:"block",color:"#7aaa90",fontSize:12,letterSpacing:1,textTransform:"uppercase",marginBottom:6,fontFamily:"sans-serif"}}>رسالة للإدارة (اختياري)</label>
              <textarea value={form.message} onChange={e=>upd("message",e.target.value)} rows={3} placeholder="يمكنك إضافة ملاحظة أو تعريف بنفسك..."
                style={{width:"100%",padding:"11px 14px",background:"rgba(255,255,255,.06)",border:"1.5px solid rgba(180,220,200,.2)",borderRadius:10,color:C.mist,fontSize:14,outline:"none",boxSizing:"border-box",fontFamily:"sans-serif",resize:"vertical"}}/>
            </div>
          </div>

          {err&&<div style={{background:"rgba(176,0,0,.12)",border:"1px solid rgba(176,0,0,.25)",borderRadius:9,padding:"10px 14px",margin:"14px 0",fontSize:13,color:"#e07070",fontFamily:"sans-serif"}}>⚠️ {err}</div>}

          <div style={{display:"flex",gap:10,marginTop:18}}>
            <button onClick={submit} disabled={saving}
              style={{flex:1,padding:"13px",background:"linear-gradient(135deg,#2e6b47,#4a9e68)",border:"none",borderRadius:11,color:"#e8f5ec",fontSize:15,cursor:"pointer",fontFamily:"'Cairo',sans-serif"}}>
              {saving?"جاري الإرسال...":"إرسال طلب الانخراط ←"}
            </button>
            <button onClick={onBack}
              style={{padding:"13px 20px",background:"transparent",border:"1px solid rgba(180,220,200,.2)",borderRadius:11,color:"#5a8070",fontSize:14,cursor:"pointer",fontFamily:"'Cairo',sans-serif"}}>
              إلغاء
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

