// FormattedTextarea — textarea stable avec boutons de formatage
function FormattedTextarea({value, onChange, rows=5, placeholder=""}) {
  const insertAt = (before, after="", sample="") => {
    const ta = document.activeElement;
    if(!ta || ta.tagName !== "TEXTAREA") {
      onChange((value||"") + before + sample + after);
      return;
    }
    const start = ta.selectionStart;
    const end = ta.selectionEnd;
    const sel = ta.value.substring(start,end) || sample;
    const newVal = ta.value.substring(0,start) + before + sel + after + ta.value.substring(end);
    onChange(newVal);
    setTimeout(()=>{
      ta.focus();
      ta.selectionStart = start + before.length;
      ta.selectionEnd = start + before.length + sel.length;
    },10);
  };

  const insertTable = () => {
    const r = prompt("عدد الصفوف (بدون رأس الجدول):", "3");
    const c = prompt("عدد الأعمدة:", "3");
    if(!r||!c) return;
    const nr = parseInt(r)||3;
    const nc = parseInt(c)||3;
    let tbl = "\n";
    // Header row
    tbl += "| " + Array(nc).fill("العنوان").join(" | ") + " |\n";
    // Separator
    tbl += "| " + Array(nc).fill("---").join(" | ") + " |\n";
    // Data rows
    for(let i=0;i<nr;i++) tbl += "| " + Array(nc).fill("   ").join(" | ") + " |\n";
    onChange((value||"") + tbl);
  };

  const btn = {
    padding:"4px 10px", border:"1px solid #c8ddd0", borderRadius:6,
    background:"#fff", cursor:"pointer", fontSize:12,
    color:"#1a4a2a", fontFamily:"sans-serif"
  };

  return (
    <div style={{border:`1.5px solid #c8ddd0`,borderRadius:9,overflow:"hidden",background:"#fafcfb"}}>
      <div style={{display:"flex",gap:4,padding:"5px 8px",borderBottom:"1px solid #c8ddd0",background:"#f0f5f2",flexWrap:"wrap",alignItems:"center"}}>
        <button style={btn} onMouseDown={e=>{e.preventDefault();insertAt("**","**","نص غامق");}}>
          <b>ع</b>
        </button>
        <button style={btn} onMouseDown={e=>{e.preventDefault();insertAt("__","__","نص مسطر");}}>
          <u>ع</u>
        </button>
        <button style={btn} onMouseDown={e=>{e.preventDefault();insertAt("*","*","نص مائل");}}>
          <i>ع</i>
        </button>
        <button style={btn} onMouseDown={e=>{e.preventDefault();insertAt("\n• ","","عنصر");}}>
          • قائمة
        </button>
        <button style={btn} onMouseDown={e=>{e.preventDefault();insertTable();}}>
          ⊞ جدول
        </button>
        <span style={{fontSize:10,color:"#999",fontFamily:"sans-serif",marginRight:"auto"}}>
          **غامق** | __مسطر__ | • قائمة | ⊞ جدول
        </span>
      </div>
      <textarea
        value={value||""}
        onChange={e=>onChange(e.target.value)}
        rows={rows}
        placeholder={placeholder}
        dir="rtl"
        style={{width:"100%",padding:"10px 14px",border:"none",fontSize:13,
          color:"#1a2a1a",background:"transparent",outline:"none",
          boxSizing:"border-box",fontFamily:"'Cairo','Tajawal',sans-serif",
          resize:"vertical",lineHeight:1.8,display:"block"}}
      />
    </div>
  );
}

// RichEditor — textarea stable avec collage depuis Word
function RichEditor({value, onChange, rows=5, placeholder=""}) {
  const taRef = React.useRef(null);

  const handlePaste = (e) => {
    // Capture HTML from clipboard (Word tables, formatted text)
    const html = e.clipboardData.getData("text/html");
    if(html && html.includes("<table")) {
      e.preventDefault();
      // Extract table as text with pipes
      const tmp = document.createElement("div");
      tmp.innerHTML = html;
      const tables = tmp.querySelectorAll("table");
      let result = value||"";
      tables.forEach(table=>{
        let tText = "\n";
        table.querySelectorAll("tr").forEach((row,ri)=>{
          const cells = row.querySelectorAll("td,th");
          tText += "| " + Array.from(cells).map(c=>c.innerText.trim()||" ").join(" | ") + " |\n";
          if(ri===0) tText += "| " + Array.from(cells).map(()=>"---").join(" | ") + " |\n";
        });
        result += tText;
      });
      // Add non-table text
      const clone = tmp.cloneNode(true);
      clone.querySelectorAll("table").forEach(t=>t.remove());
      const txt = clone.innerText;
      if(txt.trim()) result += "\n" + txt;
      onChange(result);
      return;
    }
  };

  return (
    <div style={{border:"1.5px solid #c8ddd0",borderRadius:9,overflow:"hidden",background:"#fafcfb"}}>
      <div style={{display:"flex",gap:6,padding:"6px 10px",borderBottom:"1px solid #c8ddd0",background:"#f0f5f2",alignItems:"center",flexWrap:"wrap"}}>
        <span style={{fontSize:11,color:"#555",fontFamily:"sans-serif"}}>
          💡 يمكنك كتابة النص مباشرة أو نسخ ولصق من Word (Ctrl+V)
        </span>
        <button
          style={{padding:"3px 10px",border:"1px solid #c8ddd0",borderRadius:6,background:"#fff",cursor:"pointer",fontSize:11,color:"#1a4a2a",fontFamily:"sans-serif",marginRight:"auto"}}
          onClick={()=>{
            const r=prompt("عدد الصفوف:","3");
            const c=prompt("عدد الأعمدة:","3");
            if(!r||!c) return;
            let tbl="\n";
            for(let i=0;i<parseInt(r);i++){
              tbl+="| "+Array(parseInt(c)).fill(i===0?"  العنوان  ":"          ").join(" | ")+" |\n";
              if(i===0) tbl+="| "+Array(parseInt(c)).fill("---").join(" | ")+" |\n";
            }
            const ta=taRef.current;
            const pos=ta.selectionStart;
            const newVal=(value||"").substring(0,pos)+tbl+(value||"").substring(pos);
            onChange(newVal);
          }}>
          ⊞ إدراج جدول
        </button>
      </div>
      <textarea
        ref={taRef}
        value={value||""}
        onChange={e=>onChange(e.target.value)}
        onPaste={handlePaste}
        rows={rows}
        placeholder={placeholder}
        dir="rtl"
        style={{width:"100%",padding:"10px 14px",border:"none",fontSize:13,
          color:"#1a2a1a",background:"transparent",outline:"none",
          boxSizing:"border-box",fontFamily:"'Cairo','Tajawal',sans-serif",
          resize:"vertical",lineHeight:1.8,display:"block"}}
      />
    </div>
  );
}

// SimpleEditor — éditeur simple stable pour les blocs du rapport AG
// CrTextarea — textarea non-contrôlé pour éviter les re-renders
// Utilise defaultValue (non contrôlé) donc pas de perte de focus
function CrTextarea({id, defaultValue, onSave, rows=5, placeholder=""}) {
  const ref = React.useRef(null);
  
  React.useEffect(()=>{
    if(ref.current && defaultValue !== undefined) {
      ref.current.value = defaultValue || "";
    }
  }, [defaultValue]);

  const btn = {padding:"3px 10px",border:"1px solid #c8ddd0",borderRadius:6,background:"#fff",cursor:"pointer",fontSize:12,color:"#1a4a2a",fontFamily:"sans-serif"};

  const insertFmt = (before, after) => {
    const ta = ref.current;
    if(!ta) return;
    const s = ta.selectionStart, e = ta.selectionEnd;
    const sel = ta.value.substring(s,e) || "نص";
    ta.value = ta.value.substring(0,s)+before+sel+after+ta.value.substring(e);
    ta.focus();
    ta.selectionStart = s+before.length;
    ta.selectionEnd = s+before.length+sel.length;
    if(onSave) onSave(ta.value);
  };

  return (
    <div style={{border:"1.5px solid #c8ddd0",borderRadius:9,overflow:"hidden",background:"#fafcfb"}}>
      <div style={{display:"flex",gap:4,padding:"4px 8px",borderBottom:"1px solid #c8ddd0",background:"rgba(0,0,0,.04)",flexWrap:"wrap"}}>
        <button style={btn} onMouseDown={e=>{e.preventDefault();insertFmt("**","**");}}><b>ع</b></button>
        <button style={btn} onMouseDown={e=>{e.preventDefault();insertFmt("__","__");}}><u>ع</u></button>
        <button style={btn} onMouseDown={e=>{e.preventDefault();insertFmt("[center]","[/center]");}}>↔</button>
        <button style={btn} onMouseDown={e=>{e.preventDefault();insertFmt("• ","");}}>• بند</button>
        <span style={{fontSize:10,color:"#999",fontFamily:"sans-serif",alignSelf:"center",marginRight:"auto"}}>**غامق** | __مسطر__ | ↔ وسط</span>
      </div>
      <textarea
        id={id}
        ref={ref}
        defaultValue={defaultValue||""}
        onBlur={e=>{ if(onSave) onSave(e.target.value); }}
        rows={rows}
        placeholder={placeholder}
        dir="rtl"
        style={{width:"100%",padding:"10px 14px",border:"none",fontSize:13,
          color:"#1a2a1a",background:"transparent",outline:"none",
          boxSizing:"border-box",fontFamily:"'Cairo','Tajawal',sans-serif",
          resize:"vertical",lineHeight:1.8,display:"block"}}
      />
    </div>
  );
}

