                      {role==="tresorier"&&p.statut==="confirme"&&annonce.est_payant&&(
                        <Btn style={{fontSize:12,padding:"6px 12px",background:"linear-gradient(135deg,#6a1a6a,#9a3a9a)",boxShadow:"none"}} onClick={()=>validerPaiement(p)}>💰 تسجيل الدفع</Btn>
                      )}
