                      {role==="tresorier"&&p.statut==="confirme"&&!annonce.est_payant&&(
                        <Btn style={{fontSize:12,padding:"6px 12px"}} onClick={()=>validerFinal(p)}>🏅 مصادقة نهائية</Btn>
                      )}
                      {/* Président + Admin: annuler */}
                      {(isAdmin||isPresident)&&!["annule","valide","paye"].includes(p.statut)&&(
                        <Btn variant="danger" style={{fontSize:12,padding:"6px 12px"}} onClick={()=>annuler(p)}>❌ إلغاء</Btn>
                      )}
