// IMPRESSION TAQRIR AL-JALSA AL-AMMA
// ════════════════════════════════════════════════════════════════
function printTaqrir(intro, conclusion, comptesRendus, membres, apsvtLogo, params, fmtDate) {
  const president = membres.find(m=>m.role==="president");
  const secretaire = membres.find(m=>m.role==="secretaire");
  const annee = params?.annee_courante||"2026";

  const fmt = (t) => !t ? "" : t
    .replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")
    .replace(/\n/g,"<br/>")
    .replace(/\*\*(.*?)\*\*/g,"<strong>$1</strong>")
    .replace(/__(.*?)__/g,"<u>$1</u>")
    .replace(/\[center\](.*?)\[\/center\]/g,"<div style='text-align:center'>$1</div>");

  const crByType = (type) => comptesRendus
    .filter(cr=>cr.type_evenement===type)
    .sort((a,b)=>new Date(a.date_evenement)-new Date(b.date_evenement));

  const thStyle = (color) => `background:${color};color:#fff;padding:7px 10px;border:1px solid #999;text-align:right;font-size:11px;-webkit-print-color-adjust:exact;print-color-adjust:exact`;
  const tdStyle = `padding:6px 10px;border:1px solid #ccc;font-size:11px;text-align:right;vertical-align:top`;
  const td = (v) => `<td style="${tdStyle}">${v||"—"}</td>`;

  const section = (type, color, icon, label, cols, rowFn) => {
    const rows = crByType(type);
    if(!rows.length) return "";
    return `<div style="margin-top:18px">
      <div style="background:${color};color:#fff;padding:9px 14px;border-radius:6px 6px 0 0;font-size:13px;font-weight:bold;-webkit-print-color-adjust:exact;print-color-adjust:exact">${icon} ${label}</div>
      <table style="width:100%;border-collapse:collapse;margin:0">
        <thead><tr>${cols.map(c=>`<th style="${thStyle(color)}">${c}</th>`).join("")}</tr></thead>
        <tbody>${rows.map((cr,i)=>`<tr style="background:${i%2===0?"#fff":"#f5f5f5"}">${rowFn(cr,i)}</tr>`).join("")}</tbody>
      </table></div>`;
  };

  const tables = [
    section("excursion","#2e7d32","🥾","الرحلات",["#","التاريخ","الوجهة","المكان","المُحرِّر"],(cr,i)=>td(i+1)+td(fmtDate(cr.date_evenement))+td(cr.destination||cr.titre)+td(cr.lieu)+td(cr.redacteur)),
    section("mntr_9","#b45309","🏫","منتديات التاسعة أساسي",["#","التاريخ","المكان","الموضوع","التنشيط","عدد التلاميذ"],(cr,i)=>td(i+1)+td(fmtDate(cr.date_evenement))+td(cr.lieu)+td(cr.sujet||cr.titre)+td(cr.animateurs||cr.participants)+td(cr.nb_eleves)),
    section("mntr_bac","#be185d","🎯","منتديات الباكالوريا",["#","التاريخ","المكان","الموضوع","التنشيط","عدد التلاميذ"],(cr,i)=>td(i+1)+td(fmtDate(cr.date_evenement))+td(cr.lieu)+td(cr.sujet||cr.titre)+td(cr.animateurs||cr.participants)+td(cr.nb_eleves)),
    section("olympiade","#d97706","🏆","أولمبياد",["#","التاريخ","المكان","الموضوع","إنجاز الموضوع","عدد التلاميذ","عدد الأساتذة"],(cr,i)=>td(i+1)+td(fmtDate(cr.date_evenement))+td(cr.lieu)+td(cr.sujet||cr.titre)+td(cr.animateurs)+td(cr.nb_eleves)+td(cr.nb_profs)),
    section("cafe_scientif","#0369a1","☕","المقاهي العلمية والثقافية والمحاضرات",["#","التاريخ","المكان","الموضوع","التنشيط","عدد الحاضرين"],(cr,i)=>td(i+1)+td(fmtDate(cr.date_evenement))+td(cr.lieu)+td(cr.sujet||cr.titre)+td(cr.animateurs||cr.participants)+td(cr.nb_eleves)),
    section("reunion_bureau","#1a3d7a","🏛️","اجتماعات المكتب",["#","التاريخ","المكان","القرارات الرئيسية"],(cr,i)=>td(i+1)+td(fmtDate(cr.date_evenement))+td(cr.lieu)+td((cr.decisions||"").substring(0,120))),
    section("formation","#6a1a6a","📚","التكوين",["#","التاريخ","المكان","الموضوع","التنشيط"],(cr,i)=>td(i+1)+td(fmtDate(cr.date_evenement))+td(cr.lieu)+td(cr.sujet||cr.titre)+td(cr.animateurs||cr.participants)),
  ].join("");

  const html = `<!DOCTYPE html><html dir="rtl" lang="ar">
<head><meta charset="UTF-8"><title>التقرير الأدبي للجلسة العامة — ${annee}</title>
<style>
  body{font-family:Arial,sans-serif;margin:20px;direction:rtl;color:#111;font-size:12px;}
  strong{font-weight:bold;} u{text-decoration:underline;}
  table{border-collapse:collapse;width:100%;}
  @page{margin:12mm;size:A4;}
  @media print{button{display:none!important;} table{page-break-inside:avoid;}}
</style></head>
<body>
<div style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:#f9a825;border-radius:8px;margin-bottom:16px;-webkit-print-color-adjust:exact;print-color-adjust:exact">
  <div style="text-align:right;flex:1">
    <div style="font-weight:bold;font-size:15px;color:#1a4a2a">جمعية أساتذة علوم الحياة والأرض</div>
    <div style="font-size:11px;color:#5a3a00">سوسة — تونس</div>
  </div>
  <img src="${apsvtLogo}" style="width:65px;height:65px;border-radius:50%;margin:0 12px;border:2px solid #fff" onerror="this.style.display='none'"/>
  <div style="text-align:left;flex:1">
    <div style="font-weight:bold;font-size:12px;color:#1a4a2a">Association des Professeurs des Sciences de la Vie et de la Terre</div>
    <div style="font-size:11px;color:#5a3a00">APSVT — Sousse</div>
  </div>
</div>
<div style="background:#fffde7;border:1px solid #f9a825;border-radius:8px;padding:14px;margin-bottom:16px;min-height:50px;line-height:1.8">${fmt(intro)||"<span style='color:#aaa'>لا يوجد نص مقدّمة</span>"}</div>
${tables}
<div style="background:#fce4ec;border:1px solid #e91e63;border-radius:8px;padding:14px;margin-top:16px;min-height:50px;line-height:1.8">${fmt(conclusion)||"<span style='color:#aaa'>لا يوجد نص خاتمة</span>"}</div>
<div style="display:flex;justify-content:space-between;margin-top:32px;padding-top:16px;border-top:1px solid #ccc">
  <div style="text-align:center;width:200px">
    <div style="font-weight:bold;color:#1a4a2a;margin-bottom:40px">الكاتب العام</div>
    <div style="border-top:1px solid #333;padding-top:4px;font-size:11px">${secretaire?(secretaire.prenom||"")+" "+(secretaire.nom||""):"............"}</div>
  </div>
  <div style="text-align:center;width:200px">
    <div style="font-weight:bold;color:#1a4a2a;margin-bottom:40px">رئيس الجمعية</div>
    <div style="border-top:1px solid #333;padding-top:4px;font-size:11px">${president?(president.prenom||"")+" "+(president.nom||""):"............"}</div>
  </div>
</div>
<div style="text-align:center;margin-top:20px">
  <button onclick="window.print()" style="padding:10px 24px;background:#1a4a2a;color:#fff;border:none;border-radius:8px;font-size:14px;cursor:pointer">🖨️ طباعة / حفظ PDF</button>
</div>
</body></html>`;

  const w = window.open("","_blank");
  w.document.write(html);
  w.document.close();
}

