// ═══ CODE B (fonction de vérification maintenance) ═══

// Vérification mode maintenance au démarrage
async function checkMaintenance() {
  try {
    const { db: supa } = await import("./supabase");
    const val = await supa.getParam("maintenance_active");
    return val === "true";
  } catch { return false; }
}

// ═══════════════════════════════════════════════════════════
export default function App() {
  const [screen,setScreen]=useState("loading");
  const [session,setSession]=useState(null);
  const [params,setParams]=useState({});
  const [adminPwdHash,setAdminPwdHash]=useState("");

  useEffect(()=>{
    (async()=>{
      const created=await supa.getParam("admin_created");
      const hash=await supa.getParam("admin_pwd_hash")||"";
      const annee=await supa.getParam("annee_courante")||"2025";
      const solde=await supa.getParam("solde_initial")||"1250";
      const cot=await supa.getParam("montant_cotisation")||"40";
      setAdminPwdHash(hash);
      setParams({annee_courante:annee,solde_initial:solde,montant_cotisation:cot});
      const maint = await supa.getParam("maintenance_active")||"false";
    const maintMsg = await supa.getParam("maintenance_message")||"الموقع في وضع الصيانة. سنعود قريباً.";
    setParams({...params, maintenance_active:maint, maintenance_message:maintMsg});
    setScreen(created==="true"?"public":"setup");

    })();
  },[]);

  if(screen==="loading")     return <Loader/>;
  if(screen==="setup")       return <SetupAdmin onDone={()=>setScreen("public")}/>;
  if(screen==="public"&&params.maintenance_active==="true") return <MaintenancePage message={params.maintenance_message} onAdminLogin={()=>setScreen("login")}/>;
  if(screen==="inscription") return <InscriptionPage onBack={()=>setScreen("public")} onSuccess={()=>setScreen("public")}/>;
  if(screen==="login")       return <LoginScreen onLogin={u=>{setSession(u);setScreen("app");}} onPublic={()=>setScreen("public")} onInscription={()=>setScreen("inscription")} adminPwdHash={adminPwdHash}/>;
  if(screen==="changer_pwd") return <ChangerMotDePasse session={session} onDone={u=>{setSession(u);setScreen("app");}}/>;
  return <MainApp session={session} onLogout={()=>{setSession(null);setScreen("public");}} params={params} setParams={setParams}/>;
}
