export const db = {
  async getParam(cle) { const { data } = await supabase.from('parametres').select('valeur').eq('cle', cle).single(); return data?.valeur ?? null; },
  async setParam(cle, valeur) {
    const { error } = await supabase.from('parametres').upsert({ cle, valeur }, { onConflict: 'cle' });
    return !error;
  },
  async getMembres() { const { data } = await supabase.from('membres').select('*').order('nom'); return data ?? []; },
  async addMembre(m) { const { data, error } = await supabase.from('membres').insert([m]).select().single(); return { data, error }; },
  async updateMembre(id, changes) { await supabase.from('membres').update(changes).eq('id', id); },
  async deleteMembre(id) { await supabase.from('membres').delete().eq('id', id); },
  async getMembreByEmail(email) { const { data } = await supabase.from('membres').select('*').eq('email', email).single(); return data; },
  async getMembreByCin(cin) { const { data } = await supabase.from('membres').select('*').eq('cin', cin).single(); return data; },
  async getDemandes(statut=null) { let q=supabase.from('demandes').select('*').order('created_at',{ascending:false}); if(statut)q=q.eq('statut',statut); const{data}=await q; return data??[]; },
  async addDemande(d) { const { data, error } = await supabase.from('demandes').insert([d]).select().single(); return { data, error }; },
  async updateDemande(id, changes) { await supabase.from('demandes').update(changes).eq('id', id); },
  async getDemandesByCin(cin) { const { data } = await supabase.from('demandes').select('*').eq('cin', cin); return data ?? []; },
  async getTransactions() { const { data } = await supabase.from('transactions').select('*').order('date', { ascending: false }); return data ?? []; },
  async addTransaction(t) { const { data, error } = await supabase.from('transactions').insert([t]).select().single(); return { data, error }; },
  async deleteTransaction(id) { await supabase.from('transactions').delete().eq('id', id); },
  async updateTransaction(id, changes) { await supabase.from('transactions').update(changes).eq('id', id); },
  async getDons() { const { data } = await supabase.from('dons').select('*').order('date', { ascending: false }); return data ?? []; },
  async addDon(d) { const { data, error } = await supabase.from('dons').insert([d]).select().single(); return { data, error }; },
  async deleteDon(id) { await supabase.from('dons').delete().eq('id', id); },
  async getAnnonces(publicOnly=false) { let q=supabase.from('annonces').select('*').order('date_evenement'); if(publicOnly)q=q.eq('statut','publié'); const{data}=await q; return data??[]; },
  async addAnnonce(a) { const { data, error } = await supabase.from('annonces').insert([a]).select().single(); return { data, error }; },
  async updateAnnonce(id, changes) { await supabase.from('annonces').update(changes).eq('id', id); },
  async deleteAnnonce(id) { await supabase.from('annonces').delete().eq('id', id); },

  // COMPTES RENDUS
  async getComptesRendus() { const { data } = await supabase.from('comptes_rendus').select('*').order('date_evenement', { ascending: false }); return data ?? []; },
  async addCompteRendu(cr) { const { data, error } = await supabase.from('comptes_rendus').insert([cr]).select().single(); return { data, error }; },
  async updateCompteRendu(id, changes) { await supabase.from('comptes_rendus').update(changes).eq('id', id); },
  async deleteCompteRendu(id) { await supabase.from('comptes_rendus').delete().eq('id', id); },

  // PARTICIPATIONS
  async getParticipations(annonce_id=null) {
    let q = supabase.from('participations').select('*').order('date_demande');
    if(annonce_id) q = q.eq('annonce_id', annonce_id);
    const { data } = await q; return data ?? [];
  },
  async addParticipation(p) { const { data, error } = await supabase.from('participations').insert([p]).select().single(); return { data, error }; },
  async updateParticipation(id, changes) { await supabase.from('participations').update(changes).eq('id', id); },
  async deleteParticipation(id) { await supabase.from('participations').delete().eq('id', id); },

  // STORAGE — Upload fichiers
  async uploadFichier(file) {
    const ext = file.name.split('.').pop();
    const path = `comptes-rendus/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
    const { error } = await supabase.storage.from('apsvt-documents').upload(path, file, { upsert: false });
    if (error) return { url: null, error };
    const { data } = supabase.storage.from('apsvt-documents').getPublicUrl(path);
    return { url: data.publicUrl, nom: file.name, error: null };
  },
  async deleteFichier(url) {
    const path = url.split('/apsvt-documents/')[1];
    if(path) await supabase.storage.from('apsvt-documents').remove([path]);
  },

};
