const EMAIL_SERVICE_ID = "service_qcf8l7c";
const EMAIL_TEMPLATE_ID = "template_7dpvyeu";
const EMAIL_PUBLIC_KEY = "eAY3dQM-jh2usRPdQ";
const FROM_NAME = "جمعية أساتذة علوم الحياة والأرض APSVT";

const loadEmailJS = () => new Promise((resolve) => {
  if(window.emailjs) { resolve(window.emailjs); return; }
  const script = document.createElement('script');
  script.src = 'https://cdn.jsdelivr.net/npm/@emailjs/browser@3/dist/email.min.js';
  script.onload = () => { window.emailjs.init(EMAIL_PUBLIC_KEY); resolve(window.emailjs); };
  document.head.appendChild(script);
});

export const sendEmail = async ({ to_email, to_name, subject, message }) => {
  try {
    const ejs = await loadEmailJS();
    await ejs.send(EMAIL_SERVICE_ID, EMAIL_TEMPLATE_ID, {
      to_email, to_name, subject, message,
      from_name: FROM_NAME,
      reply_to: "apsvt.tunisie@gmail.com",
    });
    console.log("Email envoyé à", to_email);
    return { success: true };
  } catch(err) {
    console.error("Erreur email:", err);
    return { success: false, error: err };
  }
};

// Extraire le nom du participant depuis les notes
const getNomParticipant = (p) => {
  if(p.notes && p.notes.includes("مشاركة بإسم:")) {
    return p.notes.replace("مشاركة بإسم: ","").replace(" (قاصر)","").trim();
  }
  return `${p.prenom||""} ${p.nom}`.trim();
};

